import XCTest
import CryptoKit
@testable import MedicLogger

final class MedicLoggerTests: XCTestCase {
    let utc = TimeZone(secondsFromGMT:0)!
    func date(_ text: String,zone: TimeZone? = nil) -> Date { let parts = text.split(separator:"T");let z = zone ?? utc;let day = DayMath.date(String(parts[0]),zone:z)!;return parts.count == 1 ? day : DayMath.time(String(parts[1]),on:day,calendar:DayMath.calendar(z))! }
    func medicine(_ data: inout AppData,monitor: Bool = false,quantity: Int? = nil,name: String = "Review medicine") throws -> Int64 { var m = Medication();m.name = name;m.monitorEffects = monitor;return try data.saveMedicine(m,quantity:quantity) }
    func testNewMedicineDoesNotMonitorEffects() throws { var data = AppData();let id = try medicine(&data);let dose = try data.take(id);XCTAssertFalse(data.doses[0].monitorEffects);XCTAssertFalse(data.doses[0].active);XCTAssertEqual(data.doses[0].status,"taken");XCTAssertThrowsError(try data.mark(dose,onset:true));XCTAssertThrowsError(try data.rate(dose,value:7)) }
    func testConcurrentDosesAreIndependent() throws { var data = AppData();let id = try medicine(&data,monitor:true);let a = try data.take(id,now:date("2026-11-01T08:00")),b = try data.take(id,now:date("2026-11-01T09:00"));try data.mark(a,onset:true,now:date("2026-11-01T10:00"));try data.mark(a,onset:false,now:date("2026-11-01T11:00"));XCTAssertFalse(data.doses.first { $0.id==a }!.active);XCTAssertTrue(data.doses.first { $0.id==b }!.active) }
    func testRatingAndValidation() throws { var data = AppData();let id = try medicine(&data,monitor:true);let s = try data.take(id);XCTAssertThrowsError(try data.rate(s,value:4));try data.mark(s,onset:false);for score in [0,7,10] { try data.rate(s,value:score);XCTAssertEqual(data.doses[0].effectiveness,score) };XCTAssertThrowsError(try data.rate(s,value:-1));XCTAssertThrowsError(try data.rate(s,value:11));try data.rate(s,value:nil);XCTAssertNil(data.doses[0].effectiveness) }
    func testMonitoringChangesOnlyAffectNewDoses() throws { var data = AppData();let id = try medicine(&data,monitor:true);let a = try data.take(id);var m = data.medicines[0];m.monitorEffects = false;_ = try data.saveMedicine(m);_ = try data.take(id);XCTAssertTrue(data.doses.first { $0.id==a }!.monitorEffects);XCTAssertFalse(data.doses.last!.monitorEffects) }
    func testStockRefundIsIdempotent() throws { var data = AppData();let id = try medicine(&data,quantity:2);let s = try data.take(id);XCTAssertEqual(data.remaining(data.medicines[0]),1);data.deleteDose(s);data.deleteDose(s);XCTAssertEqual(data.remaining(data.medicines[0]),2) }
    func testOldPackCannotRefundNewPack() throws { var data = AppData();let id = try medicine(&data,quantity:4);let old = try data.take(id);try data.refill(id,quantity:21);let new = try data.take(id);data.deleteDose(old);XCTAssertEqual(data.remaining(data.medicines[0]),20);data.deleteDose(new);XCTAssertEqual(data.remaining(data.medicines[0]),21) }
    func testStaleMedicineEditCannotChangeBatch() throws { var data = AppData();let id = try medicine(&data,quantity:4);var stale = data.medicines[0];try data.refill(id,quantity:11);stale.alias="Alias";_ = try data.saveMedicine(stale);XCTAssertEqual(data.remaining(data.medicines[0]),11) }
    func testEmptyPackAndInvalidStock() throws { var data = AppData();let id = try medicine(&data,quantity:0);XCTAssertThrowsError(try data.take(id));XCTAssertThrowsError(try data.refill(id,quantity:-1));XCTAssertEqual(data.remaining(data.medicines[0]),0) }
    func testDoseEditKeepsInventoryBinding() throws { var data = AppData();let id = try medicine(&data,quantity:5);let s = try data.take(id);var edited=data.doses[0];edited.stockBatchID=nil;edited.stockUnits=99;edited.notes="Saved";try data.saveDose(edited);XCTAssertNotNil(data.doses[0].stockBatchID);XCTAssertEqual(data.doses[0].stockUnits,1);data.deleteDose(s);XCTAssertEqual(data.remaining(data.medicines[0]),5) }
    func testArchiveProtectsHistoryAndRules() throws { var data = AppData();let id = try medicine(&data);_ = try data.take(id);XCTAssertThrowsError(try data.deleteMedicine(id));var m=data.medicines[0];m.archived=true;_ = try data.saveMedicine(m);XCTAssertThrowsError(try data.take(id));XCTAssertEqual(data.doses.count,1) }
    func testDoseChronology() throws { var d=Dose();d.takenAt=date("2026-01-03T08:00");d.onsetAt=date("2026-01-03T07:59");XCTAssertThrowsError(try d.validate());d.onsetAt=date("2026-01-03T09:00");d.endedAt=date("2026-01-03T08:30");XCTAssertThrowsError(try d.validate());d.endedAt=date("2026-01-03T10:00");XCTAssertNoThrow(try d.validate()) }
    func cycle() -> Reminder { var r=Reminder();r.frequency="cycle";r.cycleStart="2026-01-01";return r }
    func test21On7OffAndMultipleTimes() throws { var r=cycle();r.times=["08:00","20:00"];XCTAssertTrue(r.isOnDay(date("2026-01-21"),zone:utc));XCTAssertFalse(r.isOnDay(date("2026-01-22"),zone:utc));XCTAssertFalse(r.isOnDay(date("2026-01-28"),zone:utc));XCTAssertTrue(r.isOnDay(date("2026-01-29"),zone:utc));XCTAssertEqual(try r.next(after:date("2026-01-21T08:00"),zone:utc),date("2026-01-21T20:00"));XCTAssertEqual(try r.next(after:date("2026-01-21T20:00"),zone:utc),date("2026-01-29T08:00")) }
    func testFutureAnchorAndZeroOff() throws { var r=cycle();XCTAssertEqual(try r.next(after:date("2025-12-01"),zone:utc),date("2026-01-01T08:00"));r.cycleOffDays=0;XCTAssertEqual(try r.next(after:date("2026-01-21T08:00"),zone:utc),date("2026-01-22T08:00"));XCTAssertFalse(r.isOnDay(date("2025-12-31"),zone:utc)) }
    func testCycleDSTUsesCalendarDays() throws { let zone=TimeZone(identifier:"Europe/Lisbon")!;var r=cycle();r.cycleStart="2026-03-28";r.cycleOnDays=2;r.cycleOffDays=1;XCTAssertEqual(try r.next(after:date("2026-03-29T08:00",zone:zone),zone:zone),date("2026-03-31T08:00",zone:zone));XCTAssertTrue(r.isOnDay(date("2026-03-29",zone:zone),zone:zone));XCTAssertFalse(r.isOnDay(date("2026-03-30",zone:zone),zone:zone)) }
    func testDSTMissingTimeStaysOnSameDay() throws { let zone=TimeZone(identifier:"Europe/Lisbon")!;var r=Reminder();r.times=["01:30"];let next=try r.next(after:date("2026-03-29T00:00",zone:zone),zone:zone);XCTAssertEqual(DayMath.dayString(next,zone:zone),"2026-03-29");XCTAssertGreaterThan(next,date("2026-03-29T00:00",zone:zone)) }
    func testWeeklyWeekendsAndWeekdays() throws { var r=Reminder();r.frequency="weekly";r.weekDays=96;XCTAssertEqual(try r.next(after:date("2026-11-02"),zone:utc),date("2026-11-07T08:00"));r.weekDays=31;XCTAssertEqual(try r.next(after:date("2026-11-06T08:00"),zone:utc),date("2026-11-09T08:00")) }
    func testMonthly31SkipsShortMonth() throws { var r=Reminder();r.frequency="monthly";r.monthDays=[31];XCTAssertEqual(try r.next(after:date("2026-01-31T08:00"),zone:utc),date("2026-03-31T08:00")) }
    func testYearlyLeapDay() throws { var r=Reminder();r.frequency="yearly";r.yearDays=["--02-29"];XCTAssertEqual(try r.next(after:date("2026-01-01"),zone:utc),date("2028-02-29T08:00")) }
    func testInvalidReminderInputs() throws { for text in ["25:00","1:x:2","08::00","08:70","-1:00"] { XCTAssertNil(DayMath.timeParts(text)) };var r=cycle();r.cycleOnDays=0;XCTAssertThrowsError(try r.validate());r.cycleOnDays=21;r.cycleOffDays = -1;XCTAssertThrowsError(try r.validate());r.cycleOffDays=7;r.cycleStart="2026-02-30";XCTAssertThrowsError(try r.validate());r=Reminder();r.times=[];XCTAssertThrowsError(try r.validate()) }
    func testPlannerRespectsBudgetAndOffDays() throws { var data=AppData();let id=try medicine(&data);var r=cycle();r.medicineID=id;_ = try data.saveReminder(r);let plan=ReminderPlanner.plan(data,now:date("2026-01-21T09:00"),zone:utc);XCTAssertEqual(plan.count,60);XCTAssertEqual(plan.first!.date,date("2026-01-29T08:00"));XCTAssertTrue(plan.allSatisfy { r.isOnDay($0.date,zone:utc) });XCTAssertEqual(Set(plan.map(\.identifier)).count,60);data.settings.remindersEnabled=false;XCTAssertTrue(ReminderPlanner.plan(data).isEmpty) }
    func testPlannerUsesNativeRepeatsForSimpleRules() throws { var data=AppData();let id=try medicine(&data);var r=Reminder();r.medicineID=id;r.frequency="weekly";r.weekDays=31;r.times=["08:00","20:00"];_ = try data.saveReminder(r);let plan=ReminderPlanner.plan(data);XCTAssertEqual(plan.count,10);XCTAssertTrue(plan.allSatisfy(\.repeats));XCTAssertEqual(Set(plan.map { $0.components.weekday! }),Set([2,3,4,5,6])) }
    func fixture() throws -> AppData { var data=AppData();let id=try medicine(&data,monitor:true,quantity:21,name:"=Review, médecine 中文");let d=try data.take(id,now:date("2026-10-31T23:59"));try data.mark(d,onset:true,now:date("2026-11-01T00:01"));try data.mark(d,onset:false,now:date("2026-11-01T01:00"));try data.rate(d,value:7);var edited=data.doses[0];edited.notes="=2+2\n\"line\", café 中文";try data.saveDose(edited);let other=try medicine(&data,name:"Second medicine");_ = try data.take(other,now:date("2026-11-01T08:00"));return data }
    func testExportOwnEventTimestampsAndMultiMedicine() throws { let data=try fixture();let a=try ExportSelection(data:data,from:date("2026-11-01"),to:date("2026-11-01"),zone:utc);XCTAssertEqual(a.events.count,3);XCTAssertEqual(a.sessions.count,2);XCTAssertEqual(a.sessions[0].takenAt,date("2026-10-31T23:59"));let selected=Set(data.medicines.map(\.id));XCTAssertEqual(try ExportSelection(data:data,from:a.from,to:a.to,medicines:selected,zone:utc).events.count,3);XCTAssertEqual(try ExportSelection(data:data,from:a.from,to:a.to,medicines:[data.medicines[0].id],zone:utc).events.count,2);XCTAssertThrowsError(try ExportSelection(data:data,from:a.to.addingTimeInterval(86400),to:a.from,zone:utc)) }
    func testJSONSchemaRatingAndNulls() throws { let s=try ExportSelection(data:fixture(),from:date("2026-11-01"),to:date("2026-11-01"),zone:utc);let root=try JSONSerialization.jsonObject(with:ExportWriter.json(s)) as! [String:Any];XCTAssertEqual(root["schema_version"] as? Int,3);let events=root["events"] as! [[String:Any]];XCTAssertEqual(events.last?["type"] as? String,"dose_taken");let doses=root["sessions"] as! [[String:Any]];XCTAssertEqual(doses[0]["effectiveness_rating"] as? Int,7);XCTAssertTrue(doses[1]["effectiveness_rating"] is NSNull);XCTAssertEqual(doses[1]["monitor_effects"] as? Bool,false) }
    func testCSVAndXLSXDefendFormulaInjection() throws { XCTAssertEqual(ExportWriter.csvRow([" =2+2","a\"b","@evil"]),"\"' =2+2\",\"a\"\"b\",\"'@evil\"\r\n");let s=try ExportSelection(data:fixture(),from:date("2026-11-01"),to:date("2026-11-01"),zone:utc);let xml=WorkbookWriter.sheet(ExportWriter.doseHeaders,s.sessions.map(ExportWriter.doseRow),numeric:[0,1,10,11,15,16,17]);XCTAssertTrue(xml.contains("<c r=\"R2\"><v>7</v></c>"));XCTAssertFalse(xml.contains("<f>"));XCTAssertTrue(xml.contains("=Review"));XCTAssertEqual(StoredZIP.crc32(Data("123456789".utf8)),0xcbf43926) }
    func testEncryptedRoundTripRandomNoncesAndTamper() throws { let folder=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString);try FileManager.default.createDirectory(at:folder,withIntermediateDirectories:true);defer { try? FileManager.default.removeItem(at:folder) };let url=folder.appendingPathComponent("data.enc"),key=SymmetricKey(size:.bits256),storage=SecureStorage(url:url,key:key),data=try fixture();try storage.write(data);let a=try Data(contentsOf:url);XCTAssertNil(a.range(of:Data("Review".utf8)));let decoded=try storage.read();XCTAssertEqual(decoded.batches[0].createdAt.timeIntervalSince1970,data.batches[0].createdAt.timeIntervalSince1970,accuracy:0.001);var expected=data;expected.batches[0].createdAt=decoded.batches[0].createdAt;XCTAssertEqual(decoded,expected);try storage.write(data);let b=try Data(contentsOf:url);XCTAssertNotEqual(a,b);var tampered=b;tampered[tampered.count-1] ^= 1;try tampered.write(to:url);XCTAssertThrowsError(try storage.read());XCTAssertEqual(try Data(contentsOf:url),tampered);try b.write(to:url);XCTAssertThrowsError(try SecureStorage(url:url,key:SymmetricKey(size:.bits256)).read());let values=try url.resourceValues(forKeys:[.isExcludedFromBackupKey]);XCTAssertEqual(values.isExcludedFromBackup,true) }
    func testExportArtifactsForIndependentParser() throws { let s=try ExportSelection(data:fixture(),from:date("2026-11-01"),to:date("2026-11-01"),zone:utc);let folder=FileManager.default.urls(for:.documentDirectory,in:.userDomainMask)[0].appendingPathComponent("ReviewExports");try FileManager.default.createDirectory(at:folder,withIntermediateDirectories:true);for format in [ExportFormat.json,.csv,.excel,.all] { let bytes=try ExportWriter.write(s,format:format,zipped:false);try bytes.write(to:folder.appendingPathComponent("ios-review."+format.ext));XCTAssertFalse(bytes.isEmpty) } }
    func testAllFourLanguagesAndVersionFormat() { for language in ["en","fr","pt","zh"] { XCTAssertFalse(Translations.text("Settings",language:language).isEmpty);XCTAssertTrue(Translations.text("Version %s",language:language,arguments:["1.4.0"]).contains("1.4.0"));XCTAssertTrue(Translations.text("Effectiveness: %d/10",language:language,arguments:[7]).contains("7/10")) } }
    func testCustomColorContrastAcrossAppearances() {
        for hex in ["FFFFFF","FFFF00","FFD700","000000","000001","3276B5","B63840","FF00FF"] {
            for surface in ["FFFFFF","F2F2F7","1C1C1E","000000"] {
                let background=AccessibleColor.components(surface)
                for threshold in [4.5,7.0] { let adjusted=AccessibleColor.adjusted(hex,background:background,minimum:threshold);XCTAssertGreaterThanOrEqual(AccessibleColor.contrast(adjusted,background),threshold) }
            }
            let rgb=AccessibleColor.components(hex),label=AccessibleColor.luminance(rgb)>0.179 ? [0.0,0,0] : [1.0,1,1]
            XCTAssertGreaterThanOrEqual(AccessibleColor.contrast(rgb,label),4.5)
        }
    }
}
